R=[
(2355,"बिना सोया सॉस वाला कम सोडियम सॉस","अपनी पसंदीदा एशियाई रेसिपी में साधारण या कम सोडियम वाले सोया सॉस की जगह बिना सोया वाला सोया सॉस आज़माएँ। डीवीटा की डाइटिशियन एरिन ने ज़्यादा सोडियम के बिना वही स्वाद पाने का तरीका खोजा है।","15","1 बड़ा चम्मच",
["3/4 कप सिरका","2 लहसुन की कलियाँ","3 बड़े चम्मच गहरा मोलासेस (गुड़ का शीरा)","1 बड़ा चम्मच प्याज़ पाउडर"],
["सिरके को गरम करें, लेकिन उबलने न दें।","लहसुन की कलियाँ छीलकर काट लें और गरम सिरके में डालें।","ढककर रात भर फ्रिज में रखें।","छान लें और लहसुन फेंक दें।","एक काँच के जार में लहसुन वाला सिरका, मोलासेस और प्याज़ पाउडर मिलाएँ।","फ्रिज में रखें और ज़रूरत के अनुसार इस्तेमाल करें।","इस्तेमाल से पहले हल्का गरम करें और अच्छी तरह हिलाएँ।","फ्रिज में लगभग 1 महीने तक चलता है।"],
["बिना सोया वाला यह कम सोडियम सॉस फ्रिज में 1 महीने तक रखा जा सकता है।","एरिन Spice Islands® का प्याज़ पाउडर पसंद करती हैं। प्याज़ वाला नमक इस्तेमाल न करें।","मोलासेस में पोटैशियम की मात्रा अलग-अलग होती है। सबसे कम हल्के मोलासेस में है (180 mg प्रति बड़ा चम्मच), फिर गहरे मोलासेस में (210 mg/बड़ा चम्मच); ब्लैकस्ट्रैप मोलासेस में पोटैशियम बहुत ज़्यादा होता है (450 mg/बड़ा चम्मच, इसकी सलाह नहीं दी जाती)। मोलासेस गन्ने या चुकंदर के निकाले और उबाले गए रस से बनता है।","अपनी पसंद का सिरका इस्तेमाल करें। एक विकल्प के तौर पर बिना मसाले वाला राइस विनेगर देखें।"],
["1/2 सब्ज़ी, मध्यम पोटैशियम"]),
(2357,"खट्टी-मीठी खीरे की सलाद","क्या आप जानते हैं कि खीरा एक फल है? आम तौर पर इसे सब्ज़ी माना जाता है। खीरे का स्वाद हल्का और ताज़ा होता है और यह दूसरे खाद्य पदार्थों और मसालों का स्वाद आसानी से सोख लेता है। कोलोराडो की डीवीटा रीनल डाइटिशियन सैंडी ने ताज़े खीरे को प्याज़ और मीठे सिरके के मैरिनेड के साथ मिलाकर खट्टी-मीठी खीरे की सलाद बनाई है। किडनी के अनुकूल यह चटपटी सलाद हर कौर में स्वाद देती है।","6","1/2 कप",
["3 मध्यम खीरे","1 मध्यम सफ़ेद प्याज़","1/4 कप चीनी","1/2 कप व्हाइट वाइन विनेगर","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच नमक (वैकल्पिक)"],
["खीरे और प्याज़ को लगभग 1/8 इंच मोटे स्लाइस में काटें। एक बड़े कटोरे में रखें।","चीनी और सिरका मिलाएँ। चीनी पूरी तरह घुलने तक मिलाएँ। स्वाद के अनुसार और चीनी या सिरका डालें।","इसे खीरे और प्याज़ के ऊपर डालें। नमक और काली मिर्च डालें।","कटोरे को प्लास्टिक रैप से ढककर कम से कम 2 घंटे फ्रिज में रखें।","छोटे सलाद कटोरों में सलाद या नाश्ते के रूप में परोसें।"],
[],
["1 सब्ज़ी, मध्यम पोटैशियम","1/2 उच्च कैलोरी"]),
(2359,"डर्टी राइस","डर्टी राइस किडनी के अनुकूल आहार के लिए एक स्वादिष्ट साइड डिश है।","4","2/3 कप",
["3/4 कप चावल, बिना पका","2 छोटे चम्मच वनस्पति तेल","1/2 कप प्याज़","1/2 कप हरी शिमला मिर्च","1 लहसुन की कली","1 कप कम सोडियम वाला चिकन ब्रॉथ","1-1/4 कप पानी","1/2 छोटा चम्मच काली मिर्च"],
["प्याज़, हरी शिमला मिर्च और लहसुन को बारीक काट लें।","एक कैसरोल या सॉसपैन में चावल को तेल में हल्का भूरा होने तक भूनें, बीच-बीच में चलाते रहें।","प्याज़ और हरी शिमला मिर्च डालकर तब तक भूनते रहें जब तक सब्ज़ियाँ नरम न हो जाएँ, लेकिन भूरी न हों।","लहसुन डालकर 1 मिनट और पकाएँ।","ब्रॉथ, पानी और काली मिर्च डालें। ढककर उबाल आने दें; आँच कम करें और लगभग 20 मिनट तक पकाएँ, जब तक चावल पक न जाएँ।"],
["बचे हुए हिस्सों को फ्रीज़ करें या फ्रिज में रखें ताकि बाद में जल्दी से परोसा जा सके।"],
["1 स्टार्च","1/2 सब्ज़ी, कम पोटैशियम","1/2 वसा"]),
(2362,"मीठे और तीखे टॉर्टिला चिप्स","कैलिफ़ोर्निया की हमारी डीवीटा रीनल डाइटिशियन टेरी किडनी के अनुकूल मीठे और तीखे टॉर्टिला चिप्स पेश करती हैं। इन्हें घर पर बनी साइड डिश, मिठाई या नाश्ते के रूप में परोसें। इस रेसिपी से आठ हिस्से बनते हैं, जिन्हें पहले से बनाकर हवाबंद डिब्बे में बाद के लिए रखा जा सकता है।","8","6 चिप्स",
["1/4 कप मक्खन","1 छोटा चम्मच ब्राउन शुगर","1/2 छोटा चम्मच पिसा हुआ लाल मिर्च पाउडर (चिली पाउडर)","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच पिसी कायेन मिर्च","6 मैदे के टॉर्टिला, 6″ आकार के"],
["ओवन को 425° F पर पहले से गरम करें।","बेकिंग शीट पर कुकिंग स्प्रे लगाएँ।","मक्खन पिघलाएँ और एक छोटे कटोरे में ब्राउन शुगर और मसालों के साथ मिलाएँ।","हर टॉर्टिला को 8 तिकोने टुकड़ों में काटें। टुकड़ों को बेकिंग शीट पर एक परत में सजाएँ।","पेस्ट्री ब्रश से टॉर्टिला पर मसाले का मिश्रण लगाएँ।","लगभग 8 मिनट तक सुनहरा भूरा होने तक बेक करें। गरम या ठंडा परोसें।","बचे हुए चिप्स को हवाबंद डिब्बे में रखें।"],
["टॉर्टिला को आसानी से तिकोने टुकड़ों में काटने के लिए किचन कैंची इस्तेमाल करें।","कम सोडियम वाले नाश्ते के लिए मैदे के टॉर्टिला की जगह मक्के का टॉर्टिला इस्तेमाल किया जा सकता है (48 mg)। ध्यान रखें कि इसमें फॉस्फोरस ज़्यादा होता है (63 mg)।"],
["1 स्टार्च","1 वसा"]),
(2366,"एप्पल सिनेमन ब्रेड","नाश्ते के साथ आनंद लेने के लिए एप्पल सिनेमन ब्रेड का एक लोफ़ बेक करें, या किडनी के अनुकूल इस स्वादिष्ट व्यंजन को नाश्ते या मिठाई के रूप में खाएँ।","12","1 स्लाइस",
["1/2 कप बिना नमक का मक्खन","1 बड़ा सेब","1/2 कप दबाकर भरी हुई हल्की ब्राउन शुगर","1-1/2 छोटा चम्मच पिसी दालचीनी","2/3 कप दानेदार चीनी","2 बड़े अंडे","2 छोटे चम्मच वनीला एक्सट्रैक्ट","1-1/2 कप मैदा","1-1/2 छोटे चम्मच बेकिंग पाउडर","1/2 कप दूध"],
["ओवन को 350° F पर पहले से गरम करें। मक्खन को नरम होने के लिए बाहर रखें। 9 x 5 इंच के लोफ़ पैन में चिकनाई लगाएँ। सेब छीलकर बारीक काट लें।","एक कटोरे में ब्राउन शुगर और दालचीनी मिलाएँ; एक तरफ़ रख दें।","स्टैंड मिक्सर में दानेदार चीनी और मक्खन को चिकना होने तक मिलाएँ।","अंडे और वनीला डालें और मध्यम गति पर फेंटते रहें जब तक सब मिल न जाए।","मैदा और बेकिंग पाउडर डालें; मिलने तक चलाते रहें। दूध डालकर घोल में मिला लें।","तैयार घोल का आधा हिस्सा लोफ़ पैन में डालें, फिर उसके ऊपर आधे कटे हुए सेब और आधा दालचीनी-चीनी का मिश्रण डालें। बचा हुआ घोल ऊपर डालें। बचे हुए सेब डालें और चम्मच के पीछे वाले हिस्से से घोल में हल्का दबा दें। ऊपर से बचा हुआ दालचीनी-चीनी का मिश्रण डालें और फिर हल्का दबा दें।","45 से 55 मिनट तक बेक करें, या जब तक लोफ़ के बीच में डाली गई टूथपिक साफ़ न निकले। लोफ़ पैन से निकालकर कूलिंग रैक पर रखने से पहले 10 मिनट ठंडा होने दें।","ठंडे हुए लोफ़ को 3/4 इंच मोटे बारह स्लाइस में काटें।"],
["भूरी और दानेदार चीनी की जगह चीनी/चीनी के विकल्प वाले बेकिंग मिश्रण इस्तेमाल करने पर कार्बोहाइड्रेट घटकर प्रति स्लाइस 26 ग्राम और कैलोरी 197 रह जाती है।"],
["1 स्टार्च","1 उच्च कैलोरी","1-1/2 वसा"]),
(2368,"मशरूम के साथ बेक्ड फिश","वर्जीनिया की डीवीटा रीनल डाइटिशियन विकी एस. अपनी विशेषज्ञता के साथ बनाने में आसान, गॉरमे स्वाद वाली, किडनी के अनुकूल मशरूम के साथ बेक्ड फिश की रेसिपी साझा करती हैं।","4","3 औंस",
["1 पाउंड ताज़ी कॉड मछली के फ़िले","2 बड़े चम्मच मार्जरीन","1-1/2 कप कटे हुए ताज़े मशरूम","1/4 कप सफ़ेद प्याज़","1 छोटा चम्मच सूखा थाइम"],
["फ़िले को दो क्वार्ट के आयताकार बेकिंग डिश में रखें। (ताज़ी मछली की जगह फ्रोज़न मछली इस्तेमाल करने पर पहले उसे पिघला लें।)","ओवन को 450° F पर पहले से गरम करें।","प्याज़ को काट लें।","एक छोटे सॉसपैन में मार्जरीन पिघलाएँ। मशरूम और प्याज़ डालकर मध्यम आँच पर नरम होने तक पकाएँ।","मशरूम का मिश्रण मछली के ऊपर चम्मच से डालें।","सूखे थाइम को मसलकर मछली पर छिड़कें।","ओवन में बिना ढके 12 से 15 मिनट तक बेक करें, या जब तक मछली आसानी से परतों में न बिखरने लगे।"],
["विविधता के लिए तिलापिया या कोई दूसरी सफ़ेद मछली आज़माएँ।","फ्रोज़न मछली को फ्रिज में या ठंडे बहते पानी के नीचे तब तक पिघलाएँ जब तक वह लचीली न हो जाए।","1 बड़ा चम्मच ताज़ा थाइम 1 छोटे चम्मच सूखे थाइम के बराबर होता है।"],
["3 मांस","1/2 सब्ज़ी, मध्यम पोटैशियम"]),
(2372,"कुरकुरी ओवन-फ्राइड कैटफ़िश","लुइज़ियाना की डीवीटा डाइटिशियन शेरोन अपनी किडनी के अनुकूल कुरकुरी ओवन-फ्राइड कैटफ़िश की रेसिपी के साथ हाज़िर हैं, जिसमें दक्षिणी अमेरिका वाला पूरा स्वाद है और डीप-फ्राई की चर्बी बिल्कुल नहीं।","4","3 औंस",
["1 अंडे की सफ़ेदी","1/2 कप मैदा","1/4 कप कॉर्नमील (मक्के का दरदरा आटा)","1/4 कप पैंको ब्रेड क्रम्ब्स","1 छोटा चम्मच बिना नमक वाला केजुन मसाला","1 पाउंड कैटफ़िश के फ़िले"],
["ओवन को 450° F पर गरम करें।","एक चपटी, नॉनस्टिक बेकिंग शीट की सतह पर कुकिंग स्प्रे लगाएँ।","अंडे की सफ़ेदी को एक उथले कटोरे में तब तक फेंटें जब तक बहुत नरम शिखर न बनने लगें। ज़्यादा न फेंटें।","मैदा को वैक्स पेपर की एक शीट पर रखें।","वैक्स पेपर की अलग शीट पर कॉर्नमील, पैंको और केजुन मसाला मिलाएँ।","कैटफ़िश के फ़िले को काटकर कुल 4 टुकड़े बना लें। मछली को मैदे में डुबोएँ और ज़्यादा मैदा झाड़ दें।","मैदा लगी मछली को अंडे की सफ़ेदी में डुबोएँ, फिर कॉर्नमील के मिश्रण में लपेटें।","मछली को बेकिंग पैन पर रखें, और सभी फ़िले के साथ चरण 6 से 9 दोहराएँ।","मछली के फ़िले के ऊपर कुकिंग स्प्रे करें और 10 से 12 मिनट तक बेक करें, जब तक फ़िले का निचला हिस्सा भूरा न हो जाए और मछली चटचटाने न लगे। पैन को ओवन से निकालें और मछली को पलट दें।","मछली को वापस ओवन में रखें और लगभग 5 मिनट और बेक करें, जब तक फ़िले भूरे और कुरकुरे न हो जाएँ।"],
["डीवीटा का बिना नमक वाला केजुन मसाला आज़माएँ।","बिना नमक वाले केजुन मसालों के अन्य सुझाव हैं: Andy Roo’s® The Stuff with No Salt, Benoit’s® का तीखा बिना नमक वाला केजुन मसाला या Mrs. Dash® Extra Spicy मसाला मिश्रण।","पैंको जापानी ब्रेड क्रम्ब्स की एक किस्म है जिसका इस्तेमाल तली जाने वाली चीज़ों पर परत चढ़ाने के लिए होता है। यह ज़्यादातर एशियाई बाज़ारों और कई सुपरमार्केट में मिल जाता है। न मिलने पर बिना मसाले वाले सूखे ब्रेड क्रम्ब्स इस्तेमाल करें।"],
["3 मांस","1 स्टार्च"]),
(2373,"पुराने ज़माने का प्लम केक","आपने यह कहावत सुनी होगी, \"हर पुरानी चीज़ फिर से नई हो जाती है।\" ओकलाहोमा की डीवीटा डाइटिशियन सूज़न की इस स्वादिष्ट पुराने ज़माने के प्लम केक वाली मिठाई को बयान करने का यह एक अच्छा तरीका है। किडनी के अनुकूल इस रेसिपी को आज ही रात बेक करें।","12","केक का 1/12 हिस्सा",
["1/2 कप मक्खन","3/4 कप + 2 बड़े चम्मच चीनी","2 बड़े अंडे","1/2 छोटा चम्मच वनीला","1-1/2 छोटे चम्मच नींबू का रस","1 कप सफ़ेद मैदा","1/4 छोटा चम्मच बेकिंग सोडा","1-1/2 कप ताज़े आलूबुखारे (प्लम), गुठली निकाले हुए","1-1/2 छोटे चम्मच दालचीनी","12 बड़े चम्मच व्हिप्ड क्रीम"],
["ओवन को 350° F पर पहले से गरम करें। मक्खन को नरम होने के लिए बाहर रखें।","हर प्लम को 8 टुकड़ों में काटें।","एक मिक्सिंग बाउल में मक्खन और 12 बड़े चम्मच (3/4 कप) चीनी को फेंटकर क्रीम जैसा बना लें। अंडे, वनीला और नींबू का रस डालकर अच्छी तरह मिलाएँ।","मैदा और बेकिंग सोडा को एक साथ मिलाएँ। सूखी सामग्री को क्रीम जैसे मिश्रण में मिलाएँ।","घोल को चम्मच से चिकनाई लगे 8” या 9” के बेकिंग पैन में डालें। प्लम के टुकड़े छिलके वाली तरफ़ नीचे रखकर ऊपर सजाएँ।","दालचीनी को बची हुई 2 बड़े चम्मच चीनी के साथ मिलाएँ। इस मिश्रण को केक के ऊपर छिड़कें।","लगभग 40 मिनट तक बेक करें, या जब तक बीच में डाली गई टूथपिक साफ़ न निकले।","केक को ओवन से निकालकर 10 से 15 मिनट ठंडा होने दें। किनारों को ढीला करें और पैन से निकालें, दो बार पलटें ताकि प्लम वाली तरफ़ ऊपर रहे।","ऊपर से व्हिप्ड क्रीम डालें। गरम या ठंडा परोसें।"],
["रेसिपी के विश्लेषण में नमक वाला मक्खन शामिल है। चाहें तो ट्रांस-फैट रहित मार्जरीन इस्तेमाल करें।","कुछ बाद के लिए बचाकर रखें। यह केक फ्रीज़र में अच्छा रहता है।","चार बड़े प्लम से लगभग 1-1/2 कप टुकड़े मिलते हैं।"],
["1 स्टार्च","1/2 फल","2 वसा"]),
(2379,"चिकन और सेब की करी","मोनिका की स्वादिष्ट चिकन और सेब की करी से अपने किडनी आहार में थोड़ा मसाला जोड़ें। मिनेसोटा की डीवीटा रीनल डाइटिशियन मोनिका गाय के दूध की जगह राइस मिल्क और कम सोडियम वाले चिकन ब्रॉथ का इस्तेमाल करके किडनी के अनुकूल करी बनाती हैं।","8","सॉस के साथ एक चिकन ब्रेस्ट",
["8 बिना छिलके और बिना हड्डी वाले चिकन ब्रेस्ट","1/4 छोटा चम्मच काली मिर्च","2 मध्यम सेब, छीले, बीज निकाले और बारीक कटे हुए","2 छोटे प्याज़, कटे हुए","1 लहसुन की कली, बारीक कटी हुई","3 बड़े चम्मच मक्खन","1 बड़ा चम्मच करी पाउडर","1/2 बड़ा चम्मच सूखी तुलसी (बेसिल)","3 बड़े चम्मच मैदा","1 कप कम सोडियम वाला चिकन ब्रॉथ","1 कप राइस मिल्क, बिना फ़ोर्टिफ़ाइड"],
["ओवन को 350° F पर पहले से गरम करें।","चिकन ब्रेस्ट को 9” x 13” (या बड़े) बेकिंग डिश में एक परत में सजाएँ और स्वाद के अनुसार काली मिर्च डालें। एक तरफ़ रख दें।","एक सॉसपैन में सेब, प्याज़ और लहसुन को मक्खन में मध्यम आँच पर नरम होने तक भूनें।","करी पाउडर और तुलसी डालकर अच्छी तरह मिलाएँ, और एक मिनट और भूनें।","मैदा डालकर चलाएँ और एक मिनट और पकाते रहें।","चिकन ब्रॉथ और राइस मिल्क डालकर अच्छी तरह चलाएँ। आँच से उतार लें।","सॉस का मिश्रण चिकन ब्रेस्ट के ऊपर डालें और 50 से 60 मिनट तक बेक करें, या जब तक चिकन पक न जाए।"],
["मोनिका Swanson’s® का कम सोडियम वाला चिकन ब्रॉथ सुझाती हैं। परिभाषा के अनुसार, कम सोडियम वाले ब्रॉथ में प्रति कप 140 mg से ज़्यादा सोडियम नहीं होता।","ओवन में छलकने से बचाने के लिए बेक करने से पहले चिकन को ढक सकते हैं।","चिकन और सेब की करी भाप में पके सफ़ेद चावल के साथ बहुत अच्छी लगती है।","यह ज़्यादा प्रोटीन वाला भोजन है। यदि आप कम प्रोटीन वाले आहार पर हैं, तो अपनी भोजन योजना के अनुसार हिस्से को समायोजित करें।"],
["4 मांस","1/2 स्टार्च","1/4 फल, कम पोटैशियम"]),
(2380,"लेमन केक-पाई","मिसूरी की डीवीटा मरीज़ पेगी अपनी किडनी के अनुकूल लेमन केक-पाई की रेसिपी साझा करती हैं। यह मिठाई आधी केक और आधी पाई जैसी है और नींबू के स्वाद से भरपूर है।","8","9\" पाई का 1/8 हिस्सा",
["1 कप चीनी","1 बड़ा चम्मच बिना नमक का मक्खन","2 अंडे, ज़र्दी और सफ़ेदी अलग किए हुए","2 बड़े चम्मच सफ़ेद मैदा","2 छोटे चम्मच कद्दूकस किया हुआ नींबू का छिलका","2 बड़े चम्मच ताज़ा नींबू का रस","1 कप दूध","1 पाई शेल, 9″ आकार का, बिना बेक किया हुआ"],
["ओवन को 450° F पर पहले से गरम करें।","चीनी और मक्खन को क्रीम जैसा होने तक फेंटें। फेंटी हुई अंडे की ज़र्दी डालकर चलाएँ।","मैदा, नींबू का छिलका, नींबू का रस और दूध डालें। मिलाने के लिए चलाएँ।","अंडे की सफ़ेदी को तब तक फेंटें जब तक वह कड़ी न हो जाए, लेकिन सूखी नहीं, और शिखर न बनने लगें। सफ़ेदी को नींबू के मिश्रण में धीरे से मिलाएँ, ज़्यादा न मिलाएँ।","फिलिंग को पाई शेल में डालें और 450° F पर 10 मिनट बेक करें। आँच घटाकर 325° F करें और 20 मिनट और बेक करें, या जब तक फिलिंग जम न जाए और ऊपर से सुनहरा भूरा न हो जाए।"],
["कार्बोहाइड्रेट ज़्यादा होने के कारण मधुमेह वाले लोगों को सलाह दी जाती है कि वे सुझाए गए हिस्से का आधा टुकड़ा ही लें।"],
["1 स्टार्च","2 वसा","1 उच्च कैलोरी"]),
(2389,"इटैलियन मीटबॉल","एक पारंपरिक व्यंजन का किडनी के अनुकूल रूप, यह इटैलियन मीटबॉल रेसिपी किडनी रोग, मधुमेह वाले या डायलिसिस पर रहने वाले लोगों की ज़रूर पसंदीदा बनेगी।","24","2 मीटबॉल",
["1 कप रोस्टेड रेड पेपर टमाटर सॉस","1 कप प्याज़","3 बड़े अंडे","3 पाउंड बीफ़ का कीमा","1 कप ओटमील, बिना पका","6 बड़े चम्मच पार्मेसन चीज़","1 बड़ा चम्मच जैतून का तेल","1 बड़ा चम्मच लहसुन पाउडर","2 छोटे चम्मच सूखा ओरेगैनो","1 छोटा चम्मच पिसी काली मिर्च"],
["रोस्टेड रेड पेपर टमाटर सॉस तैयार करें। एक तरफ़ रख दें।","ओवन को 375° F पर पहले से गरम करें। प्याज़ काट लें।","एक बड़े कटोरे में अंडे फेंटें, फिर सारी सामग्री डालकर मिलाएँ।","1” के गोले बनाकर बेकिंग शीट पर रखें।","10 से 15 मिनट तक बेक करें, जब तक मीटबॉल अंदर तक पक न जाएँ।","परोसने के लिए मीटबॉल को वार्मिंग डिश या स्लो कुकर में कम आँच पर रखें। 2 छोटे चम्मच सॉस अलग से साथ में परोसें या सॉस को मीटबॉल पर डाल दें।"],
["रोस्टेड रेड पेपर टमाटर सॉस की रेसिपी DaVita.com पर देखें। इसमें एक बड़े चम्मच में 37 mg पोटैशियम और 21 mg सोडियम होता है। कम पोटैशियम और कम सोडियम वाले इस सॉस को कई व्यंजनों में टमाटर सॉस की जगह इस्तेमाल किया जा सकता है।","मीटबॉल पहले से बनाकर फ्रिज में रखें। परोसते समय सब कुछ साथ गरम करें और वार्मिंग डिश में डालें।"],
["1-1/2 मांस","1 वसा"]),
(2396,"एंजेल कुकीज़","डीवीटा की मरीज़ वांडा अपनी एंजेल कुकीज़ की रेसिपी साझा करती हैं, एक ऐसी मिठाई जो बेहद स्वर्गीय और हल्की है। सिर्फ़ 4 सामग्री वाली यह आसान मिठाई किडनी के अनुकूल होने के साथ-साथ मधुमेह वालों के लिए भी बढ़िया है।","36","2",
["1 डिब्बा एंजेल फ़ूड केक मिक्स","1 छोटा चम्मच वनीला एक्सट्रैक्ट","1/2 कप ब्लैक चेरी डाइट सोडा","14 औंस सूखे, मीठे नारियल के फ्लेक्स"],
["ओवन को 350° F पर पहले से गरम करें।","एक मिक्सिंग बाउल में केक मिक्स, वनीला और सोडा मिलाएँ। यदि मिश्रण बहुत कड़ा हो या पूरी तरह न मिले, तो एक-एक चम्मच और सोडा डालें, बस मिलने भर के लिए।","नारियल को धीरे से मिलाएँ।","कुकी शीट पर पार्चमेंट पेपर बिछाएँ। कुकी के मिश्रण का एक-एक चम्मच शीट पर 2″ की दूरी पर रखें। 10 मिनट बेक करें, जब तक नीचे से हल्का भूरा न हो जाए।","कुकीज़ को बेकिंग शीट से निकालें और कूलिंग रैक पर ठंडा करें।"],
["कुकीज़ के हर नए सेट के लिए पार्चमेंट पेपर की नई शीट इस्तेमाल करें।","रखने के लिए ज़िप वाले बैग या बंद डिब्बे में रखें।","सोडा के दूसरे फ्लेवर भी इस्तेमाल किए जा सकते हैं: चेरी, स्ट्रॉबेरी, क्रैनबेरी आदि। फॉस्फेट वाले एडिटिव्स युक्त सोडा से बचें।"],
["1 स्टार्च","1/2 वसा"]),
(2397,"घर की बनी चेरी पाई","इस घर की बनी चेरी पाई का एक टुकड़ा किसी भी भोजन का मीठा अंत है या दिन के बीच में ताज़गी पाने का बढ़िया तरीका। किडनी के अनुकूल इस रेसिपी से आपकी चखी हुई सबसे अच्छी पाई में से एक बनाएँ।","8","1/8 पाई",
["16 औंस डिब्बाबंद चेरी, जूस में, गुठली निकली हुई","2 बड़े चम्मच कॉर्नस्टार्च","1/2 कप चीनी","2 कप सफ़ेद मैदा","14 बड़े चम्मच बिना नमक वाला टब मार्जरीन","1/4 छोटा चम्मच नमक","1/4 कप बर्फ़ जैसा ठंडा पानी"],
["चेरी का जूस एक मापने वाले कप में निथार लें। एक कप बनाने के लिए पानी मिलाएँ।","एक मध्यम सॉसपैन में चीनी और कॉर्नस्टार्च मिलाएँ। धीरे-धीरे चेरी का जूस डालें।","जूस के मिश्रण को मध्यम आँच पर तब तक गरम करें जब तक वह गाढ़ा होने न लगे। अलग रखी चेरी डालें और फिर से गरम करें जब तक फिलिंग में बुलबुले न उठने लगें। ठंडा होने के लिए एक तरफ़ रख दें। क्रस्ट तैयार करें।","एक मध्यम कटोरे में मैदा और नमक मिलाएँ। पेस्ट्री ब्लेंडर या दो चाकुओं से मार्जरीन के बड़े चम्मच भर टुकड़े मैदे में काटकर मिलाएँ, जब तक मिश्रण मटर के दाने जितने टुकड़े न बनाने लगे।","बर्फ़ जैसा ठंडा पानी बस इतना मिलाएँ कि गोला बन जाए। इसे फ्रिज में 30 मिनट आराम करने दें।","ओवन को 425 ºF पर पहले से गरम करें।","आटे को दो हिस्सों में बाँटें। आटे लगी सतह पर आधे आटे को 8” या 9” के गोल पाई पैन के आकार में बेलें। पाई क्रस्ट को पैन में रखें और चेरी की फिलिंग डालें। दूसरे आधे आटे को बेलकर पाई के ऊपर रखें।","पाई के किनारों को दबाकर बंद करें। क्रस्ट में चीरे लगाएँ। भूरा करने के लिए क्रस्ट पर थोड़ा दूध या अंडा लगाएँ। 20 से 25 मिनट तक बेक करें, जब तक क्रस्ट भूरा न हो जाए और चेरी में बुलबुले न उठने लगें।"],
["मधुमेह वाले लोग चीनी की जगह Splenda® दानेदार स्वीटनर इस्तेमाल कर सकते हैं। कार्बोहाइड्रेट घटकर 31 ग्राम रह जाता है और कार्बोहाइड्रेट विकल्प 2 के बराबर होते हैं।","चेरी की खटास के अनुसार चीनी घटाएँ-बढ़ाएँ।","पोषक तत्वों के विश्लेषण में चेरी में मिलाई गई 3/4 कप चीनी शामिल है।"],
["1 फल, कम पोटैशियम","1-1/2 स्टार्च","3-1/2 वसा","1/2 उच्च कैलोरी"]),
(2398,"मसालेदार समर वेजिटेबल मिक्स","मसालेदार समर वेजिटेबल मिक्स तीखे स्वाद वाली, किडनी के अनुकूल रेसिपी है।","4","1/2 कप",
["1/4 कप प्याज़","1/4 कप लाल शिमला मिर्च","1 कप ज़ुकीनी (तोरी)","4 छोटे चम्मच कैनोला तेल","1/2 कप स्वीट कॉर्न के दाने","1/4 कप कटे हुए ताज़े मशरूम","1/8 छोटा चम्मच काली मिर्च","1 चुटकी लाल मिर्च के फ्लेक्स","1/3 कप पानी","1 बड़ा चम्मच बोतलबंद बारबेक्यू सॉस"],
["प्याज़ को छोटे चौकोर टुकड़ों में काटें, शिमला मिर्च को जूलियन शैली में पतली लंबी फाँकों में काटें और ज़ुकीनी के स्लाइस बना लें।","कड़ाही में तेल, प्याज़ और मक्का डालकर मध्यम-तेज़ आँच पर गरम करें। 8 से 10 मिनट तक बार-बार चलाते हुए पकाएँ, जब तक प्याज़ पारदर्शी न हो जाए और मक्का भूरा होने न लगे।","शिमला मिर्च, ज़ुकीनी, मशरूम, काली मिर्च, मिर्च के फ्लेक्स और पानी डालें। चलाकर ढक दें। 3 से 5 मिनट तक पकाएँ, जब तक ज़ुकीनी नरम न हो जाए और पानी सूख न जाए।","आँच से उतारें और बारबेक्यू सॉस मिलाएँ। 4 हिस्सों में बाँटकर परोसें।"],
["ताज़े मक्के के 1 मध्यम भुट्टे से 3/4 से 1 कप दाने मिलते हैं। आप फ्रोज़न या कम सोडियम वाला डिब्बाबंद मक्का भी इस्तेमाल कर सकते हैं।","1 मध्यम आकार की ज़ुकीनी से 1 कप कटे हुए टुकड़े मिलते हैं।","जूलियन का मतलब है पतली, लंबी पट्टियों में काटना।","लेबल की तुलना करके सबसे कम सोडियम वाला बाज़ार का बारबेक्यू सॉस चुनें।"],
["1 सब्ज़ी, मध्यम पोटैशियम","1/2 स्टार्च","1/2 वसा"]),
(2400,"स्लो कुकर एशियन चिकन","क्या आपको चाइनीज़ खाना, सब्ज़ियों का कुरकुरापन और चटपटे सॉस पसंद हैं? स्लो कुकर एशियन चिकन में यह सब है और इसे बनाना बहुत आसान है। इंडियाना की डीवीटा रीनल डाइटिशियन एंजी कहती हैं कि किडनी के अनुकूल इस रेसिपी को सुबह तैयार करके पूरे दिन धीमी आँच पर पकने के लिए छोड़ा जा सकता है और जब आप चाहें, रात के खाने के लिए यह पूरी तरह पका हुआ तैयार मिलेगा।","6","1 चिकन ब्रेस्ट, 1/2 कप सब्ज़ियाँ और 1/2 कप चावल",
["2 मध्यम गाजर","2 हरे प्याज़","4 सेलरी की डंडियाँ","1 लहसुन की कली","8 औंस डिब्बाबंद बाँस के कोंपल (बैंबू शूट्स)","8 औंस डिब्बाबंद वाटर चेस्टनट","2 बड़े चम्मच वनस्पति तेल","6 बिना हड्डी और बिना छिलके वाले चिकन ब्रेस्ट","1 कप कम सोडियम वाला चिकन ब्रॉथ","1 बड़ा चम्मच ब्राउन शुगर","1/4 कप कम सोडियम वाला सोया सॉस","1/4 छोटा चम्मच कुटी लाल मिर्च के फ्लेक्स","1/4 कप कॉर्नस्टार्च","1/3 कप पानी","3 कप पके हुए सफ़ेद चावल"],
["गाजर, हरे प्याज़ और सेलरी को काट लें। लहसुन को कुचल लें। बाँस के कोंपल और वाटर चेस्टनट को धोकर काट लें।","कड़ाही में तेल गरम करें और चिकन को सभी तरफ़ से भूरा करें।","चिकन को स्लो कुकर में डालें।","कॉर्नस्टार्च और पानी को छोड़कर सारी सामग्री डालें। चलाएँ, फिर ढककर धीमी आँच (लो सेटिंग) पर 6 से 8 घंटे पकाएँ।","स्लो कुकर को हाई पर कर दें। कॉर्नस्टार्च और ठंडे पानी को चिकना होने तक मिलाएँ, फिर स्लो कुकर के तरल में मिला दें। भाप निकलने के लिए स्लो कुकर का ढक्कन थोड़ा खुला रखें। हाई पर लगभग 15 मिनट तक गाढ़ा होने तक पकाएँ।","चिकन और सब्ज़ियों को चावल के ऊपर परोसें।"],
["कम प्रोटीन वाली भोजन योजना के लिए हिस्से को 1/2 चिकन ब्रेस्ट कर लें।","सफ़ेद या ब्राउन चावल के साथ परोसें।"],
["4 मांस","2 सब्ज़ी, मध्यम पोटैशियम","2 स्टार्च"]),
]
